def _copy_plan_prices(apps, schema_editor):
    Plan = apps.get_model("payments", "Plan")
    PlanPrice = apps.get_model("payments", "PlanPrice")
    Subscription = apps.get_model("payments", "Subscription")

    for plan in Plan.objects.all():
        price = (
            PlanPrice.objects.filter(plan_id=plan.pk)
            .order_by("-is_active", "id")
            .first()
        )
        if price is None:
            continue
        plan.amount = price.amount
        plan.currency = price.currency
        plan.billing_interval = price.billing_interval
        plan.stripe_price_id = price.stripe_price_id
        plan.save(update_fields=["amount", "currency", "billing_interval", "stripe_price_id"])

    for subscription in Subscription.objects.all():
        if not subscription.plan_price_id:
            continue
        price = PlanPrice.objects.filter(pk=subscription.plan_price_id).first()
        if price is None:
            continue
        subscription.plan_id = price.plan_id
        subscription.amount = price.amount
        subscription.currency = price.currency
        subscription.billing_interval = price.billing_interval
        subscription.stripe_price_id = price.stripe_price_id or ""
        subscription.save(
            update_fields=[
                "plan",
                "amount",
                "currency",
                "billing_interval",
                "stripe_price_id",
            ]
        )

